// sigma=125*338/564=74.9 CSS px (Figma blur radius/2).
const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="964" height="751" viewBox="-200 -180 964 751"><defs><linearGradient id="g" gradientUnits="userSpaceOnUse" x1="357.44609539792265" y1="29.927124402117528" x2="128.77686180167072" y2="10.781824764269883"><stop offset="0" stop-color="#21338E"/><stop offset="1" stop-color="#080C25"/></linearGradient><filter id="b" filterUnits="userSpaceOnUse" x="-1600" y="-1600" width="4500" height="4500" color-interpolation-filters="sRGB"><feGaussianBlur stdDeviation="125"/></filter></defs><g filter="url(#b)"><g transform="matrix(0.8915125727653503 0.4529959559440613 -0.4529959559440613 0.8915125727653503 210.7921752929688 -18)"><ellipse cx="236.48451232910156" cy="110.14690399169922" rx="236.48451232910156" ry="110.14690399169922" fill="url(#g)"/></g></g></svg>\n`;
const mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'application/javascript; charset=utf-8','.webp':'image/webp','.svg':'image/svg+xml','.woff2':'font/woff2','.woff':'font/woff','.mp4':'video/mp4','.json':'application/json'};
async function startServer(){server=http.createServer((req,res)=>{try{const u=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname);if(!u.startsWith('/bagira-preview/')){res.writeHead(404);res.end();return;}let f=path.resolve(repo,u.slice('/bagira-preview/'.length));if(f!==repo&&!f.startsWith(repo+path.sep)){res.writeHead(403);res.end();return;}if(fs.existsSync(f)&&fs.statSync(f).isDirectory())f=path.join(f,'index.html');if(!fs.existsSync(f)||!fs.statSync(f).isFile()){res.writeHead(404);res.end();return;}res.writeHead(200,{'Content-Type':mime[path.extname(f).toLowerCase()]||'application/octet-stream','Cache-Control':'no-store'});fs.createReadStream(f).pipe(res);}catch{res.writeHead(500);res.end();}});await new Promise((ok,no)=>{server.once('error',no);server.listen(0,'127.0.0.1',ok)});return `http://127.0.0.1:${server.address().port}/bagira-preview/`;}
function dependency(name){const candidates=[path.join(base,'BAGIRA_V46_TOOLS','node_modules',name),path.join(base,'BAGIRA_PLAYWRIGHT_TEMP','node_modules',name),path.join(base,'BAGIRA_V41_TOOLS','node_modules',name),name];for(const p of candidates){try{return require(p)}catch(e){if(e.code!=='MODULE_NOT_FOUND')throw e}}throw Error('Missing '+name+'; existing V46 tools folder expected.');}

const widths=[320,375,393,430,767,820,1024,1280,1440];
async function capture(stage,url){const folder=path.join(qa,stage);mkdir(folder);let rows=[];for(const width of widths){const page=await browser.newPage({viewport:{width,height:900},deviceScaleFactor:1,reducedMotion:'reduce'});try{page.on('pageerror',e=>report.errors.push({stage,width,error:e.message}));await page.goto(url+'ohrana-doma/',{waitUntil:'load',timeout:45000});await page.evaluate(async()=>{await document.fonts.ready;await Promise.all([...document.querySelectorAll('.service-hero img,.site-header img')].map(e=>e.decode().catch(()=>{})));});await page.waitForTimeout(200);const m=await page.evaluate(()=>{const q=s=>document.querySelector(s),r=e=>{if(!e)return null;const b=e.getBoundingClientRect();return {x:b.x,y:b.y,w:b.width,h:b.height}},hero=q('.service-hero--highlights-compact'),house=q('.service-hero__background'),p=getComputedStyle(house,'::before');return {header:r(q('.site-header')),hero:r(hero),inner:r(q('.service-hero__inner')),house:r(house),image:r(house.querySelector('img')),badge:r(q('.service-hero__visual')),title:r(q('.service-hero__content h1')),copy:r(q('.service-hero__content p')),cta:r(q('.service-hero__mobile-cta')),highlights:r(q('.service-hero__highlights')),application:r(q('.service-application--smartphone-alarm')),scrollWidth:document.documentElement.scrollWidth,glow:{content:p.content,background:p.backgroundImage,display:p.display,zIndex:p.zIndex,width:p.width,height:p.height},houseLoaded:house.querySelector('img').naturalWidth>0}});for(const [key,sel] of [['hero','.service-hero__inner'],['header','.site-header']]){await page.locator(sel).screenshot({path:path.join(folder,`${width}-${key}.png`),animations:'disabled',timeout:30000});}rows.push({width,...m});console.log(`${stage} ${width}px complete`);}finally{await page.close();}}return rows;}
async function compare(sharp,a,b){const x=await sharp(a).ensureAlpha().raw().toBuffer({resolveWithObject:true}),y=await sharp(b).ensureAlpha().raw().toBuffer({resolveWithObject:true});if(x.info.width!==y.info.width||x.info.height!==y.info.height)return {sameSize:false,differingPixels:null,maxDelta:null};let n=0,max=0;for(let i=0;i<x.data.length;i+=4){let d=0;for(let j=0;j<4;j++)d=Math.max(d,Math.abs(x.data[i+j]-y.data[i+j]));if(d)n++;max=Math.max(max,d);}return {sameSize:true,differingPixels:n,maxDelta:max};}
async function main(){mkdir(qa);console.log('BAGIRA V47 — MOBILE HERO GLOW / LOCAL QA ONLY\nQA: '+qa);cp.execFileSync('git',['-c','core.autocrlf=false','clone','--no-hardlinks','--no-checkout',workspace,repo],{stdio:'inherit'});git('checkout','--detach',baseline);check(git('rev-parse','HEAD')===baseline,'Baseline mismatch');check(!git('status','--porcelain'),'Clone not clean');const file=path.join(repo,target),old=fs.readFileSync(file,'utf8');check(sha(Buffer.from(old))==='1d3d9f829044007f7d39af9fd1ac567c69c5c01b83e264ace9580abf8cd3ba19','Published HTML hash mismatch');check(old.includes('bagira-mobile-header-v46g')&&old.includes('bagira-equipment-v44e')&&old.includes('bagira-ellipses-v38')&&!old.includes('bagira-hero-glow-v47'),'Expected markers mismatch');check(old.split('</head>').length===2,'Unexpected head');check(!fs.existsSync(path.join(repo,asset)),'SVG already exists');const pw=dependency('playwright'),sharp=dependency('sharp');let last;for(const opt of [{},{channel:'msedge'},{channel:'chrome'}]){try{browser=await pw.chromium.launch({headless:true,...opt});break}catch(e){last=e}}if(!browser)throw last;const url=await startServer();report.before=await capture('BEFORE',url);const next=fs.readFileSync(path.join(workspace,target),'utf8');const candidateSvg=fs.readFileSync(path.join(workspace,asset),'utf8');check(sha(Buffer.from(next))==="eb9e446c8b939cf829a8aa1dccadbd91d9649bdc9ac9882bf1d5bd4d72d5b012",'Candidate HTML hash mismatch');check(sha(Buffer.from(candidateSvg))==="ee9479bc8c92b3c9e1f0af8a63a4c246dd8d5526c42bab87bebfea61c50070dc",'Candidate SVG hash mismatch');check(next===old.replace('</head>',css+'\n</head>')&&candidateSvg===svg,'Candidate patch mismatch');fs.writeFileSync(file,next,'utf8');fs.writeFileSync(path.join(repo,asset),candidateSvg,'utf8');report.after=await capture('AFTER',url);const failures=[],test=(ok,msg)=>{if(!ok)failures.push(msg)};report.comparisons=[];for(const m of report.after){const b=report.before.find(v=>v.width===m.width),label=m.width+'px ';for(const k of ['header','hero','inner','house','image','badge','title','copy','cta','highlights','application']){test(JSON.stringify(b[k])===JSON.stringify(m[k]),label+k+' geometry changed');}test(m.scrollWidth===b.scrollWidth,label+' scroll width changed');test(m.houseLoaded,label+' house not loaded');const h=await compare(sharp,path.join(qa,'BEFORE',m.width+'-header.png'),path.join(qa,'AFTER',m.width+'-header.png')),c=await compare(sharp,path.join(qa,'BEFORE',m.width+'-hero.png'),path.join(qa,'AFTER',m.width+'-hero.png'));report.comparisons.push({width:m.width,header:h,hero:c});test(h.sameSize&&h.differingPixels===0,label+' header pixels changed');if(m.width<=767){test(m.glow.background.includes('hero-mobile-v47.svg')&&m.glow.content==='""'&&m.glow.display==='block',label+' glow missing');test(c.sameSize&&c.differingPixels>0,label+' no visible glow / size changed');}else test(c.sameSize&&c.differingPixels===0,label+' desktop/tablet hero pixels changed');}
const files=git('ls-files','-z').split('\0').filter(Boolean);test(files.filter(f=>/\.webp$/i.test(f)).length===119&&!files.some(f=>/\.(png|jpe?g|gif|bmp|tiff?|avif)$/i.test(f)),'Raster standard');const changed=git('status','--porcelain','-z').split('\0').filter(Boolean).map(s=>s.trim());test(changed.length===2&&changed.includes('M '+target)&&changed.includes('?? '+asset),'Unexpected changed files');test(!report.errors.length,'Browser errors');git('diff','--check');report.hashes={[target]:sha(Buffer.from(next)),[asset]:sha(Buffer.from(svg))};report.failures=failures;report.checks=['9 widths, hero geometry and header preserved','mobile glow visible; desktop/tablet hero pixel equality','119 WebP unchanged; one HTML and one new SVG only; no push'];report.status=failures.length?'REVIEW_REQUIRED':'LOCAL_CANDIDATE_READY';save();fs.writeFileSync(path.join(qa,'V47.css'),css,'utf8');fs.writeFileSync(path.join(qa,'hero-mobile-v47.svg'),svg,'utf8');fs.writeFileSync(path.join(qa,'00_OPEN_COMPARE.html'),`<!doctype html><meta charset="utf-8"><title>V47</title><style>body{background:#151823;color:white;font:16px Arial;margin:24px}img{max-width:100%;height:auto}.row{display:grid;grid-template-columns:1fr 1fr;gap:20px}</style><h1>V47 — эллипс за домом</h1>${widths.map(w=>`<h2>${w}px</h2><div class="row"><div>До<br><img src="BEFORE/${w}-hero.png"></div><div>После<br><img src="AFTER/${w}-hero.png"></div></div>`).join('')}`);console.log(report.status+' | failures='+failures.length+'\nQA: '+qa);if(failures.length)process.exitCode=1;}
main().catch(e=>{report.status='STOP';report.error=e.message;try{save()}catch{}console.error('STOP: '+e.message+'\nNo publication. QA: '+qa);process.exitCode=1;}).finally(async()=>{if(browser)await browser.close();if(server)await new Promise(ok=>server.close(ok));});
